import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (id: string, weightGrams?: number, qty = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(799);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(799);
  });

  it("returns 0 when subtotal meets free-over threshold", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(calc.computeShippingCents([line("a")], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds free-over threshold", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(calc.computeShippingCents([line("a")], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal is below free-over threshold", () => {
    const calc = new FlatShippingCalculator(799, 5000);
    expect(calc.computeShippingCents([line("a")], 4999)).toBe(799);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a")], 1000)).toBe(0);
  });

  it("accepts 0 freeOverCents (always free)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([line("a")], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets list", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 1.5, costCents: 100 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 1000, costCents: 99.9 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          50.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 10000)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", undefined, 3)], 10000)).toBe(0);
  });

  it("selects the first bracket whose upToGrams >= weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    // weight = 500 → fits first bracket
    expect(calc.computeShippingCents([line("a", 500)], 10000)).toBe(300);
    // weight = 501 → second bracket
    expect(calc.computeShippingCents([line("a", 501)], 10000)).toBe(600);
    // weight = 1000 → second bracket exactly
    expect(calc.computeShippingCents([line("a", 1000)], 10000)).toBe(600);
    // weight = 1001 → third bracket
    expect(calc.computeShippingCents([line("a", 1001)], 10000)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([line("a", 5000)], 10000)).toBe(2000);
  });

  it("defaults overflow to heaviest bracket cost when overflowCostCents is omitted", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 5000)], 10000)).toBe(600);
  });

  it("sorts brackets internally even if provided out of order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 2000, costCents: 800 },
      { upToGrams: 500, costCents: 300 },
    ]);
    // weight 400 should match 500 bracket
    expect(calc.computeShippingCents([line("a", 400)], 10000)).toBe(300);
    // weight 600 should match 2000 bracket
    expect(calc.computeShippingCents([line("a", 600)], 10000)).toBe(800);
  });

  it("accumulates weight across multiple lines and quantities", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 3000, costCents: 1000 },
    ]);
    // 200*3 + 500*2 = 1600 → second bracket
    const lines: CartLine[] = [line("a", 200, 3), line("b", 500, 2)];
    expect(calc.computeShippingCents(lines, 10000)).toBe(1000);
  });
});

import { describe, it, expect, vi } from "vitest";
