describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, plus fixed 200 = 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // max(0, -500) + 300 = 300
      expect(composite.computeDiscountCents(10000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("works with a single child", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(25)],
        "sum",
      );
      expect(composite.computeDiscountCents(4000)).toBe(1000);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 10000 = 1000 → remaining 9000
      // Second: 10% of 9000 = 900 → total discount 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("ordering matters in chain mode", () => {
      // FixedAmount 500 first, then 10%
      const a = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 500 off 10000 → remaining 9500, then 10% of 9500 = 950 → total 1450
      expect(a.computeDiscountCents(10000)).toBe(1450);

      // 10% first, then FixedAmount 500
      const b = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 10% of 10000 = 1000 → remaining 9000, then min(500, 9000) = 500 → total 1500
      expect(b.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // 100% of 10000 = 10000 → remaining 0, then min(max(0, 500), 0) = 0
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -100) = 0 → remaining stays 5000, then min(200, 5000) = 200
      expect(composite.computeDiscountCents(5000)).toBe(200);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(10000)).toBe(300);
  });
});
"}

